Here's a **high-quality, production-ready Cypress testing framework** that leverages:

- **Docker** for consistent environments
- **Cypress screenshot generation** with custom naming, storage, and preservation
- **Custom test reporting** and **clean architecture**
- **Environment configuration** via `.env` files
- **Test organization** via page objects and reusable utilities

---

### ✅ Project Structure

```bash
cypress-framework/
│
├── cypress/
│   ├── e2e/
│   │   ├── login.spec.cy.js
│   │   └── home.spec.cy.js
│   ├── fixtures/
│   │   └── example.json
│   └── support/
│       ├── commands.js
│       ├── index.js
│       └── e2e/
│           └── config.ts
│
├── docker/
│   ├── Dockerfile
│   └── docker-compose.yml
│
├── cypress.config.ts
├── package.json
├── README.md
└── cypress
```

---

### 1. `cypress.config.ts`

```ts
import { defineConfig } from 'cypress';
import type { Config } from 'cypress';

const config: Config = {
  chromeWebSecurity: false,
  viewportWidth: 1280,
  viewportHeight: 720,

  // Record video only in CI mode
  video: true,

  // Screenshots
  screenshotOnRunFailure: true,
  screenshotDelay: 2000,

  // Save screenshots to a directory with dynamic naming
  screenshotsFolder: 'cypress/screenshots',
  screenshotOnRunFailure: true,
  videoCompression: 32,

  // Backup screenshots only after failing tests
  retries: {
    runMode: 2,
    openMode: 0,
  },

  // Customizing folder structure
  baseUrl: 'http://localhost:3000',
  defaultCommandTimeout: 8000,
  pageLoadTimeout: 60000,
  responseTimeout: 50000,

  // ENV variables
  env: {
    API_URL: 'http://localhost:8080/api',
  },

  // Test reporting
  reporter: 'cypress-multi-reporters',
  reporterOptions: {
    configFile: 'reporter-config.json',
  },

  // Custom scripts and test setup
  setupNodeEvents(on, config) {
    on('after:screenshot', (_options, screenshot) => {
      const timestamp = new Date().toISOString().replace(/[:.]/g, '-');
      const testTitle = config.spec?.name?.replace(/\s/g, '_') || 'unknown';

      const newScreenshotPath = `cypress/screenshots/${testTitle}-${timestamp}.png`;
      cy.task('renameScreenshot', {
        oldPath: screenshot.path,
        newPath: newScreenshotPath,
      });
      return newScreenshotPath;
    });

    // Use Docker-based Cypress run
    on('before:browser:launch', (browser, launchOptions) => {
      if (browser.name === 'chrome') {
        launchOptions.args.push('--no-sandbox');
        launchOptions.args.push('--disable-dev-shm-usage');
      }
      return launchOptions;
    });

    return config;
  },
};

export default defineConfig(config);
```

---

### 2. `cypress/support/commands.js`

```js
// Custom command to wait for network stability
Cypress.Commands.add('waitForNetworkIdle', (timeout = 5000) => {
  cy.window().then(win => {
    cy.wrap(win, { log: false }).its('fetch').should('not.be.undefined');
    cy.window().then(win => {
      const mutationObserver = new MutationObserver(() => {
        const networkRequests = win.performance.getEntriesByType("fetch") || [];
        if (networkRequests.length === 0) {
          mutationObserver.disconnect();
          cy.log("Network idle");
        }
      });

      mutationObserver.observe(document, { childList: true, subtree: true });
      cy.wait(timeout);
      mutationObserver.disconnect();
    });
  });
});

Cypress.Commands.add('assertElementExists', (selector) => {
  cy.get(selector).should('be.visible');
});

// Task to rename screenshots after capture
Cypress.task('renameScreenshot', ({ oldPath, newPath }) => {
  const fs = require('fs');
  fs.renameSync(oldPath, newPath);
  return true;
});
```

---

### 3. `cypress/e2e/home.spec.cy.js`

```js
describe('Home Page Tests', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should display the homepage title', () => {
    cy.get('h1').should('contain', 'Welcome to My App');
    cy.screenshot('home-page-title');
  });

  it('should render the main content section', () => {
    cy.get('main').should('be.visible');
    cy.screenshot('home-main-content');
  });

  it('should display a button with correct text', () => {
    cy.get('button').contains('Get Started').should('be.visible');
    cy.screenshot('home-get-started-button');
  });

  it('should redirect on button click', () => {
    cy.get('button').click();
    cy.url().should('include', '/dashboard');
    cy.screenshot('dashboard-redirect');
  });
});
```

---

### 4. `cypress/support/index.js`

```js
// Import custom commands
import './commands';
import './e2e/config';

// Add custom Cypress functions
Cypress.on('fail', (err, runnable) => {
  if (Cypress.currentTest.state === 'failed') {
    cy.screenshot(`failed-test-${Cypress.currentTest.title}`);
  }
  return false; // continue failing the test
});
```

---

### 5. Docker Setup

#### `docker/Dockerfile`

```dockerfile
# Base image with Node.js and Chrome
FROM cypress/browsers:node18.16.0-chrome114-ff113

# Create app directory
WORKDIR /app

# Copy package files
COPY package*.json ./

# Install dependencies
RUN npm ci

# Copy source files
COPY . .

# Install Cypress for headless execution
RUN npx cypress install --force

# Set environment variables
ENV NODE_ENV=development

# Serve the app on port 3000
EXPOSE 3000

# If you're running your app on the same container, use:
# CMD ["npm", "start"]
```

> ⚠️ This assumes you're running your application **inside** or **beside** the Cypress container.

---

#### `docker/docker-compose.yml`

```yaml
version: '3.8'

services:
  app:
    build:
      context: .
      dockerfile: docker/Dockerfile
    ports:
      - "3000:3000"
    environment:
      - CYPRESS_VIDEO=failures
      - CYPRESS_SILENT=true
    volumes:
      - ./cypress:/app/cypress
      - ./node_modules:/app/node_modules
    command: npm run dev

  cypress:
    build:
      context: .
      dockerfile: docker/Dockerfile
    depends_on:
      - app
    volumes:
      - ./cypress:/app/cypress
      - ./cypress/screenshots:/app/cypress/screenshots
      - ./cypress/videos:/app/cypress/videos
    environment:
      - CYPRESS_BASE_URL=http://app:3000
      - CYPRESS_VIDEO=true
      - CYPRESS_SCREENSHOTS=true
    command: |
      npm run cypress:run \
        -- --spec cypress/e2e/*.cy.js \
        --headed \
        --record \
        --key YOUR_CYPRESS_RECORD_KEY

  # Optional: For running Cypress dashboard
  # Use `cypress run --record --key <KEY>` and store in env
```

---

### 6. `package.json` Scripts

```json
{
  "scripts": {
    "test:cy:run": "cypress run",
    "test:cy:open": "cypress open",
    "test:cy:headless": "cypress run --headless --browser chrome",
    "cypress:run": "cypress run --headed --spec cypress/e2e/*.cy.js --browser chrome",
    "cypress:headless": "cypress run --headless --spec cypress/e2e/*.cy.js --browser chrome",
    "cypress:docker": "docker compose up --build cypress",
    "test": "npm run test:cy:headless"
  }
}
```

---

### 7. Environment Variables (`.env`)

```env
CYPRESS_BASE_URL=http://localhost:3000
CYPRESS_RECORD_KEY=your-cypress-record-key
CYPRESS_SILENT=true
```

> 📌 Never commit `.env` to Git

---

### 8. `reporter-config.json`

```json
{
  "reporter": "mocha-junit-reporter",
  "reporterOptions": {
    "mochaFile": "cypress/reports/results-[hash].xml"
  }
}
```

Install with:

```bash
npm install cypress-multi-reporters mocha-junit-reporter
```

