## ✅ Step 3: Initialize SDL & Load Images

Here's a full example (`main.c`):

```c
// main.c
#include <SDL2/SDL.h>
#include <SDL2/SDL_image.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include "snake.h"

#define SCREEN_WIDTH 800
#define SCREEN_HEIGHT 600
#define GRID_SIZE 20
#define CELL_SIZE (SCREEN_WIDTH / GRID_SIZE)

int main(int argc, char* argv[]) {
    SDL_Init(SDL_INIT_VIDEO);
    IMG_Init(IMG_INIT_PNG);

    SDL_Window* window = SDL_CreateWindow("Snake Game", SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED,
                                          SCREEN_WIDTH, SCREEN_HEIGHT, SDL_WINDOW_SHOWN);
    SDL_Renderer* renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);

    // Load Images
    SDL_Texture* background = loadTexture(renderer, "resources/background.png");
    SDL_Texture* snakeHead = loadTexture(renderer, "resources/snake_head.png");
    SDL_Texture* snakeBody = loadTexture(renderer, "resources/snake_body.png");
    SDL_Texture* foodTex = loadTexture(renderer, "resources/food.png");
    SDL_Texture* tile = loadTexture(renderer, "resources/tile.png");

    // Initialize game
    Snake* snake = createSnake();
    Vector2 foodPos = {rand() % GRID_SIZE, rand() % GRID_SIZE};

    int running = 1;
    Uint32 lastTime = SDL_GetTicks();
    float deltaTime = 0.0f;

    while (running) {
        Uint32 now = SDL_GetTicks();
        deltaTime = (now - lastTime) / 1000.0f;
        lastTime = now;

        // Handle Events
        SDL_Event e;
        while (SDL_PollEvent(&e)) {
            if (e.type == SDL_QUIT) {
                running = 0;
            }
            if (e.type == SDL_KEYDOWN) {
                switch (e.key.keysym.sym) {
                    case SDLK_UP: moveSnake(snake, UP); break;
                    case SDLK_DOWN: moveSnake(snake, DOWN); break;
                    case SDLK_LEFT: moveSnake(snake, LEFT); break;
                    case SDLK_RIGHT: moveSnake(snake, RIGHT); break;
                }
            }
        }

        // Update game
        updateSnake(snake, deltaTime);
        checkCollision(snake, &foodPos);

        // Render
        SDL_RenderClear(renderer);

        // Draw background
        drawTexture(renderer, background, 0, 0, SCREEN_WIDTH, SCREEN_HEIGHT);

        // Draw grid or tiles (optional)
        for (int i = 0; i < GRID_SIZE; i++) {
            for (int j = 0; j < GRID_SIZE; j++) {
                drawTexture(renderer, tile, i * CELL_SIZE, j * CELL_SIZE, CELL_SIZE, CELL_SIZE);
            }
        }

        // Draw food
        drawTexture(renderer, foodTex, foodPos.x * CELL_SIZE, foodPos.y * CELL_SIZE, CELL_SIZE, CELL_SIZE);

        // Draw snake
        for (int i = 0; i < snake->length; i++) {
            Vector2 pos = snake->body[i];
            if (i == 0) {
                drawTexture(renderer, snakeHead, pos.x * CELL_SIZE, pos.y * CELL_SIZE, CELL_SIZE, CELL_SIZE);
            } else {
                drawTexture(renderer, snakeBody, pos.x * CELL_SIZE, pos.y * CELL_SIZE, CELL_SIZE, CELL_SIZE);
            }
        }

        SDL_RenderPresent(renderer);

        // Cap FPS (~60 FPS)
        float targetTime = 1.0f / 60.0f;
        if (deltaTime < targetTime) {
            SDL_Delay((Uint32)((targetTime - deltaTime) * 1000));
        }
    }

    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
    IMG_Quit();
    SDL_Quit();

    return 0;
}
```

