Here's a JavaScript function that takes an array of 5 numbers and checks if any of them is a prime number, printing the prime numbers to the console:

```javascript
function checkForPrimes(numbers) {
  // Ensure the input is an array with exactly 5 numbers
  if (!Array.isArray(numbers) || numbers.length !== 5) {
    console.log("Please provide an array of exactly 5 numbers.");
    return;
  }

  // Function to check if a number is prime
  function isPrime(num) {
    // Numbers less than 2 are not prime
    if (num < 2) {
      return false;
    }
    // 2 is prime
    if (num === 2) {
      return true;
    }
    // Even numbers > 2 are not prime
    if (num % 2 === 0) {
      return false;
    }
    // Check for odd divisors up to sqrt(num)
    for (let i = 3; i <= Math.sqrt(num); i += 2) {
      if (num % i === 0) {
        return false;
      }
    }
    return true;
  }

  // Check each number in the array
  for (let i = 0; i < numbers.length; i++) {
    const num = numbers[i];

    // Ensure the value is a number
    if (typeof num !== 'number' || isNaN(num)) {
      console.log(`${num} is not a valid number.`);
      continue;
    }

    // Check if the number is prime
    if (isPrime(num)) {
      console.log(`${num} is a prime number.`);
    }
  }
}

// Example usage:
checkForPrimes([4, 7, 10, 13, 15]); // Outputs: 7 is a prime number. 13 is a prime number.
checkForPrimes([1, 2, 3, 4, 5]);    // Outputs: 2 is a prime number. 3 is a prime number. 5 is a prime number.
checkForPrimes([8, 9, 14, 18, 21]); // No output (no primes in the array)
```

