Here's a C++ program that reads a text file line by line and counts the number of occurrences of a specific word:

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <sstream>
#include <algorithm>
#include <cctype>

// Function to convert string to lowercase for case-insensitive comparison
std::string toLower(const std::string& str) {
    std::string result = str;
    std::transform(result.begin(), result.end(), result.begin(), ::tolower);
    return result;
}

// Function to check if a word appears in a line
bool containsWord(const std::string& line, const std::string& targetWord) {
    std::istringstream iss(line);
    std::string word;

    while (iss >> word) {
        // Remove punctuation and convert to lowercase for comparison
        std::string cleanWord = "";
        for (char c : word) {
            if (std::isalnum(c)) {
                cleanWord += std::tolower(c);
            }
        }

        if (cleanWord == targetWord) {
            return true;
        }
    }
    return false;
}

// Function to count occurrences of a word in a file
int countWordOccurrences(const std::string& filename, const std::string& targetWord) {
    std::ifstream file(filename);
    int count = 0;

    if (!file.is_open()) {
        std::cerr << "Error: Could not open file " << filename << std::endl;
        return -1;
    }

    std::string line;
    std::string target = toLower(targetWord);

    while (std::getline(file, line)) {
        if (containsWord(line, target)) {
            count++;
        }
    }

    file.close();
    return count;
}

// Function to perform a case-insensitive comparison of strings
bool equalsIgnoreCase(const std::string& s1, const std::string& s2) {
    return toLower(s1) == toLower(s2);
}

