    std::cout << "Enter the name of the text file: ";
    std::getline(std::cin, filename);

    std::cout << "Enter the word to search for: ";
    std::getline(std::cin, targetWord);

    if (filename.empty() || targetWord.empty()) {
        std::cerr << "Error: Filename and search word cannot be empty." << std::endl;
        return 1;
    }

    // Count occurrences using advanced method (handles punctuation and case)
    int occurrences = countWordOccurrencesAdvanced(filename, targetWord);

    if (occurrences >= 0) {
        std::cout << "The word '" << targetWord << "' appears " << occurrences 
                  << " times in the file." << std::endl;
    }

    return 0;
}
